slice-a-boxes.sourceCode:
// Slice A: a bounding box per cluster of /perception/object_recognition/debug/clusters.
// The clustering's objects carry only a centroid, so the boxes come from the cluster
// points. Upstream writes each cluster's points in a row, cluster i in colour i % 6, so a
// change of colour starts the next cluster and box i belongs to object i. A box is the
// smallest rectangle around the points in the ground plane (yaw searched in 1° steps),
// from the lowest point to the highest.
import {
  CubePrimitive,
  LinePrimitive,
  LineType,
  SceneUpdate,
  TextPrimitive,
} from "@foxglove/schemas";

export const inputs = ["/perception/object_recognition/debug/clusters"];
export const output = "/studio_script/slice_a/boxes";

type PointCloud2 = {
  header: { stamp: { sec: number; nsec: number }; frame_id: string };
  width: number;
  height: number;
  point_step: number;
  is_bigendian: boolean;
  fields: { name: string; offset: number }[];
  data: Uint8Array;
};
type Cluster = { rgb: number; x: number[]; y: number[]; z: number[] };
type Box = { x: number; y: number; z: number; yaw: number; dx: number; dy: number; dz: number };

// A box at least this thick on each axis, in metres, so a flat cluster stays visible.
const MIN_EXTENT = 0.1;

function clustersOf(cloud: PointCloud2): Cluster[] {
  const offset = (name: string): number => {
    const field = cloud.fields.find((f) => f.name === name);
    if (field === undefined) {
      throw new Error(`the cloud has no field '${name}'`);
    }
    return field.offset;
  };
  const [ox, oy, oz, orgb] = ["x", "y", "z", "rgb"].map(offset);
  const view = new DataView(cloud.data.buffer, cloud.data.byteOffset, cloud.data.byteLength);
  const little = !cloud.is_bigendian;
  const clusters: Cluster[] = [];
  for (let i = 0; i < cloud.width * cloud.height; i++) {
    const base = i * cloud.point_step;
    const rgb = view.getUint32(base + orgb, little);
    let cluster = clusters[clusters.length - 1];
    if (cluster === undefined || cluster.rgb !== rgb) {
      cluster = { rgb, x: [], y: [], z: [] };
      clusters.push(cluster);
    }
    cluster.x.push(view.getFloat32(base + ox, little));
    cluster.y.push(view.getFloat32(base + oy, little));
    cluster.z.push(view.getFloat32(base + oz, little));
  }
  return clusters;
}

function boxOf(cluster: Cluster): Box {
  const { x, y, z } = cluster;
  let best = { area: Infinity, yaw: 0, u0: 0, u1: 0, v0: 0, v1: 0 };
  for (let degrees = 0; degrees < 90; degrees++) {
    const yaw = (degrees * Math.PI) / 180;
    const c = Math.cos(yaw);
    const s = Math.sin(yaw);
    let u0 = Infinity;
    let u1 = -Infinity;
    let v0 = Infinity;
    let v1 = -Infinity;
    for (let i = 0; i < x.length; i++) {
      const u = x[i] * c + y[i] * s;
      const v = -x[i] * s + y[i] * c;
      u0 = Math.min(u0, u);
      u1 = Math.max(u1, u);
      v0 = Math.min(v0, v);
      v1 = Math.max(v1, v);
    }
    const area = (u1 - u0) * (v1 - v0);
    if (area < best.area) {
      best = { area, yaw, u0, u1, v0, v1 };
    }
  }
  const c = Math.cos(best.yaw);
  const s = Math.sin(best.yaw);
  const u = (best.u0 + best.u1) / 2;
  const v = (best.v0 + best.v1) / 2;
  let z0 = Infinity;
  let z1 = -Infinity;
  for (const height of z) {
    z0 = Math.min(z0, height);
    z1 = Math.max(z1, height);
  }
  return {
    x: u * c - v * s,
    y: u * s + v * c,
    z: (z0 + z1) / 2,
    yaw: best.yaw,
    dx: Math.max(best.u1 - best.u0, MIN_EXTENT),
    dy: Math.max(best.v1 - best.v0, MIN_EXTENT),
    dz: Math.max(z1 - z0, MIN_EXTENT),
  };
}

// The 8 corners of a unit box, corner i at the sign bits of i, and its 12 edges: the
// pairs of corners that differ in one bit.
const CORNERS = [0, 1, 2, 3, 4, 5, 6, 7].map((i) => ({
  x: i & 1 ? 0.5 : -0.5,
  y: i & 2 ? 0.5 : -0.5,
  z: i & 4 ? 0.5 : -0.5,
}));
const EDGES = [0, 1, 2, 3, 4, 5, 6, 7].flatMap((i) =>
  [1, 2, 4].filter((bit) => (i & bit) === 0).flatMap((bit) => [i, i | bit]),
);

export default function script(event: { message: PointCloud2 }): SceneUpdate {
  const { header } = event.message;
  const cubes: CubePrimitive[] = [];
  const lines: LinePrimitive[] = [];
  const texts: TextPrimitive[] = [];
  clustersOf(event.message).forEach((cluster, index) => {
    const box = boxOf(cluster);
    const pose = {
      position: { x: box.x, y: box.y, z: box.z },
      orientation: { x: 0, y: 0, z: Math.sin(box.yaw / 2), w: Math.cos(box.yaw / 2) },
    };
    const r = ((cluster.rgb >> 16) & 0xff) / 255;
    const g = ((cluster.rgb >> 8) & 0xff) / 255;
    const b = (cluster.rgb & 0xff) / 255;
    cubes.push({
      pose,
      size: { x: box.dx, y: box.dy, z: box.dz },
      color: { r, g, b, a: 0.2 },
    });
    lines.push({
      type: 2 as LineType, // LINE_LIST
      pose,
      thickness: 2,
      scale_invariant: true,
      points: CORNERS.map((p) => ({ x: p.x * box.dx, y: p.y * box.dy, z: p.z * box.dz })),
      color: { r, g, b, a: 1 },
      colors: [],
      indices: EDGES,
    });
    texts.push({
      pose: { position: { x: box.x, y: box.y, z: box.z + box.dz / 2 + 0.6 }, orientation: pose.orientation },
      billboard: true,
      font_size: 14,
      scale_invariant: true,
      color: { r: 1, g: 1, b: 1, a: 1 },
      text: `#${index}`,
    });
  });
  return {
    deletions: [],
    entities: [
      {
        timestamp: header.stamp,
        frame_id: header.frame_id,
        id: "slice_a_boxes",
        lifetime: { sec: 0, nsec: 0 },
        frame_locked: false,
        metadata: [],
        arrows: [],
        cubes,
        spheres: [],
        cylinders: [],
        lines,
        triangles: [],
        texts,
        models: [],
      },
    ],
  };
}

slice-a-object-count.sourceCode:
// Slice A: the number of detected objects in each frame, for the plot.
export const inputs = ["/perception/object_recognition/detection/objects"];
export const output = "/studio_script/slice_a/object_count";

type Output = { count: number };

export default function script(event: { message: { objects: unknown[] } }): Output {
  return { count: event.message.objects.length };
}

isuzu-ego.sourceCode:
// Isuzu localization (#110): the bus and its trail in map, from the EKF's odometry.
// The bus is a box approximated from the bag's sensor mounts, not its drawings: the sensor
// kit sits 6.2 m ahead of base_link at the front, the side lidars 1.27 m left and right.
// The trail keeps the EKF's positions; it starts again when the player loops and time
// goes back.
import { CubePrimitive, LinePrimitive, LineType, SceneUpdate, TextPrimitive } from "@foxglove/schemas";

export const inputs = ["/localization/pose_twist_fusion_filter/kinematic_state"];
export const output = "/studio_script/isuzu/ego";

type Time = { sec: number; nsec: number };
type Odometry = {
  header: { stamp: Time; frame_id: string };
  pose: { pose: { position: { x: number; y: number; z: number } } };
  twist: { twist: { linear: { x: number } } };
};

// The bus, in base_link: from 3.0 m behind to 6.5 m ahead, 2.5 m wide, 3.0 m high.
const REAR = 3.0;
const FRONT = 6.5;
const WIDTH = 2.5;
const HEIGHT = 3.0;
// Trail points kept: a minute at 50 Hz.
const TRAIL = 3000;

let trail: { x: number; y: number; z: number }[] = [];
let lastNanos = -Infinity;

export default function script(event: { message: Odometry }): SceneUpdate {
  const odom = event.message;
  const stamp = odom.header.stamp;
  const nanos = stamp.sec * 1e9 + stamp.nsec;
  if (nanos < lastNanos) {
    trail = [];
  }
  lastNanos = nanos;
  const p = odom.pose.pose.position;
  trail.push({ x: p.x, y: p.y, z: p.z });
  if (trail.length > TRAIL) {
    trail = trail.slice(trail.length - TRAIL);
  }
  const speed = odom.twist.twist.linear.x;
  const identity = { x: 0, y: 0, z: 0, w: 1 };
  const bus: CubePrimitive = {
    pose: { position: { x: (FRONT - REAR) / 2, y: 0, z: HEIGHT / 2 }, orientation: identity },
    size: { x: FRONT + REAR, y: WIDTH, z: HEIGHT },
    color: { r: 0.98, g: 0.8, b: 0.18, a: 0.35 },
  };
  const label: TextPrimitive = {
    pose: { position: { x: 0, y: 0, z: HEIGHT + 1.2 }, orientation: identity },
    billboard: true,
    font_size: 14,
    scale_invariant: true,
    color: { r: 1, g: 0.92, b: 0.55, a: 1 },
    text: `Isuzu bus  ${(speed * 3.6).toFixed(1)} km/h`,
  };
  const path: LinePrimitive = {
    type: LineType.LINE_STRIP,
    pose: { position: { x: 0, y: 0, z: 0 }, orientation: identity },
    thickness: 0.35,
    scale_invariant: false,
    points: trail,
    color: { r: 0.98, g: 0.8, b: 0.18, a: 0.9 },
    colors: [],
    indices: [],
  };
  const entity = (id: string, frame: string) => ({
    timestamp: stamp,
    frame_id: frame,
    id,
    lifetime: { sec: 0, nsec: 0 },
    frame_locked: true,
    metadata: [],
    arrows: [],
    cubes: [],
    spheres: [],
    cylinders: [],
    lines: [],
    triangles: [],
    texts: [],
    models: [],
  });
  const busEntity = { ...entity("bus", "base_link"), cubes: [bus], texts: [label] };
  const trailEntity = { ...entity("trail", "map"), lines: [path] };
  return { deletions: [], entities: [busEntity, trailEntity] };
}
